1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { and, eq } from "drizzle-orm";
4	import { inboxDismissals, joinRequests } from "@paperclipai/db";
5	import { sidebarBadgeService } from "../services/sidebar-badges.js";
6	import { accessService } from "../services/access.js";
7	import { dashboardService } from "../services/dashboard.js";
8	import { collapseDuplicatePendingHumanJoinRequests } from "../lib/join-request-dedupe.js";
9	import { assertCompanyAccess } from "./authz.js";
10	
11	function buildDismissedAtByKey(
12	  dismissals: Array<{ itemKey: string; dismissedAt: Date | string }>,
13	): Map<string, number> {
14	  return new Map(
15	    dismissals.map((dismissal) => [dismissal.itemKey, new Date(dismissal.dismissedAt).getTime()]),
16	  );
17	}
18	
19	export function sidebarBadgeRoutes(db: Db) {
20	  const router = Router();
21	  const svc = sidebarBadgeService(db);
22	  const access = accessService(db);
23	  const dashboard = dashboardService(db);
24	
25	  router.get("/companies/:companyId/sidebar-badges", async (req, res) => {
26	    const companyId = req.params.companyId as string;
27	    assertCompanyAccess(req, companyId);
28	    let canApproveJoins = false;
29	    if (req.actor.type === "board") {
30	      canApproveJoins =
31	        req.actor.source === "local_implicit" ||
32	        Boolean(req.actor.isInstanceAdmin) ||
33	        (await access.canUser(companyId, req.actor.userId, "joins:approve"));
34	    } else if (req.actor.type === "agent" && req.actor.agentId) {
35	      canApproveJoins = await access.hasPermission(companyId, "agent", req.actor.agentId, "joins:approve");
36	    }
37	
38	    const visibleJoinRequests = canApproveJoins
39	      ? collapseDuplicatePendingHumanJoinRequests(
40	        await db
41	          .select({
42	            id: joinRequests.id,
43	            requestType: joinRequests.requestType,
44	            status: joinRequests.status,
45	            requestingUserId: joinRequests.requestingUserId,
46	            requestEmailSnapshot: joinRequests.requestEmailSnapshot,
47	            updatedAt: joinRequests.updatedAt,
48	            createdAt: joinRequests.createdAt,
49	          })
50	          .from(joinRequests)
51	          .where(and(eq(joinRequests.companyId, companyId), eq(joinRequests.status, "pending_approval")))
52	      ).map(({ id, updatedAt, createdAt }) => ({
53	        id,
54	        updatedAt,
55	        createdAt,
56	      }))
57	      : [];
58	
59	    const dismissedAtByKey =
60	      req.actor.type === "board" && req.actor.userId
61	        ? await db
62	          .select({ itemKey: inboxDismissals.itemKey, dismissedAt: inboxDismissals.dismissedAt })
63	          .from(inboxDismissals)
64	          .where(and(eq(inboxDismissals.companyId, companyId), eq(inboxDismissals.userId, req.actor.userId)))
65	          .then(buildDismissedAtByKey)
66	        : new Map<string, number>();
67	
68	    const badges = await svc.get(companyId, {
69	      dismissals: dismissedAtByKey,
70	      joinRequests: visibleJoinRequests,
71	    });
72	    const summary = await dashboard.summary(companyId);
73	    const hasFailedRuns = badges.failedRuns > 0;
74	    const alertsCount =
75	      (summary.agents.error > 0 && !hasFailedRuns ? 1 : 0) +
76	      (summary.costs.monthBudgetCents > 0 && summary.costs.monthUtilizationPercent >= 80 ? 1 : 0);
77	    badges.inbox = badges.failedRuns + alertsCount + badges.joinRequests + badges.approvals;
78	
79	    res.json(badges);
80	  });
81	
82	  return router;
83	}
